/**
 * gemini_cli_hook.ts — Kyberion ↔ Gemini CLI hook entry point.
 *
 * Invoked by .gemini/settings.json hooks (generated by
 * scripts/generate_provider_hook_configs.ts). Reads the hook event JSON from
 * stdin and the event name from argv[2], drives the co-session bridge, and
 * writes the Gemini-shaped response to stdout.
 *
 *   node dist/scripts/gemini_cli_hook.js SessionStart < event.json
 *   node dist/scripts/gemini_cli_hook.js BeforeAgent  < event.json
 *   node dist/scripts/gemini_cli_hook.js BeforeTool   < event.json
 *   node dist/scripts/gemini_cli_hook.js SessionEnd   < event.json
 *
 * Everything here is fail-open: a broken co-session store must not wedge the
 * user's Gemini session. BeforeTool deny is the only affirmative output — an
 * empty response leaves the decision to Gemini CLI.
 */
import {
  coSessionHookDrain,
  coSessionHookEnd,
  coSessionHookJoin,
  coSessionHookLeaseGate,
  formatPendingHandoffs,
} from '@agent/core/provider/co-session-hook';
import { isRecord } from '@agent/core/foundation/text';
import { parseSafeJsonInput } from '@agent/core/foundation/safe-json';
import { currentProcessArgv, defineScript, isDirectScript } from './lib/harness.js';

/** Gemini CLI write-file tools whose target path we can lease-check. */
const WRITE_TOOLS = new Set(['write_file', 'replace']);
const PATH_KEYS = ['file_path', 'path', 'notebook_path'] as const;

async function readStdin(): Promise<string> {
  if (process.stdin.isTTY) return '';
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString('utf8').trim();
}

export function parseGeminiHookPayload(raw: string): Record<string, unknown> {
  if (!raw) return {};
  try {
    const parsed = parseSafeJsonInput(raw, 'Gemini CLI hook payload');
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function targetPaths(toolInput: Record<string, unknown> = {}): string[] {
  for (const key of PATH_KEYS) {
    const candidate = toolInput[key];
    if (typeof candidate === 'string' && candidate) return [candidate];
  }
  return [];
}

function contextOutput(additionalContext: string): string {
  return JSON.stringify({ hookSpecificOutput: { additionalContext } });
}

/**
 * Handle one hook event. Returns the JSON string to print on stdout, or
 * undefined for silence (advisory/no-op — Gemini CLI treats empty output as
 * "no decision"). Pure of stdin/stdout so it stays unit-testable.
 */
export function handleGeminiHookEvent(
  event: string,
  payload: Record<string, unknown>
): string | undefined {
  const sessionKey = payload.session_id as string | undefined;

  switch (event) {
    case 'SessionStart': {
      const join = coSessionHookJoin({
        provider: 'gemini',
        session_key: sessionKey,
        note: 'joined via Gemini SessionStart hook',
      });
      if (!join.joined) return undefined;
      return contextOutput(
        `Kyberion co-session ${join.session_id}: joined as ${join.participant_id}. ` +
          'Acquire a path lease before editing shared paths: ' +
          `\`co-session lease --action acquire --as gemini --participant-id ${join.participant_id} --path <repo/path>\`. ` +
          'Pending handoffs are injected on each prompt.'
      );
    }
    case 'BeforeAgent': {
      const block = formatPendingHandoffs(
        coSessionHookDrain({ provider: 'gemini', session_key: sessionKey })
      );
      return block ? contextOutput(block) : undefined;
    }
    case 'BeforeTool': {
      try {
        if (!WRITE_TOOLS.has(String(payload.tool_name ?? ''))) return undefined;
        for (const filePath of targetPaths(payload.tool_input as Record<string, unknown>)) {
          const gate = coSessionHookLeaseGate({
            provider: 'gemini',
            session_key: sessionKey,
            file_path: filePath,
          });
          if (gate.decision === 'deny') {
            return JSON.stringify({
              decision: 'deny',
              reason: `Kyberion co-session lease gate: ${gate.reason}`,
            });
          }
        }
      } catch {
        // fail-open: advisory stays advisory on errors
      }
      return undefined;
    }
    case 'SessionEnd': {
      try {
        coSessionHookEnd({ provider: 'gemini', session_key: sessionKey });
      } catch {
        // best-effort cleanup; TTL reclaim is the safety net
      }
      return undefined;
    }
    default:
      return undefined;
  }
}

export async function main(args: string[] = currentProcessArgv()): Promise<void> {
  const event = args[2] ?? '';
  const raw = await readStdin();
  const payload = parseGeminiHookPayload(raw);
  const output = handleGeminiHookEvent(event, payload);
  if (output) process.stdout.write(output);
}

export const runGeminiCliHook = defineScript({
  name: 'gemini-cli-hook',
  run: async ({ argv }) => {
    await main(['node', 'gemini_cli_hook', ...argv]);
  },
});

if (
  isDirectScript(import.meta.url, 'gemini_cli_hook.ts') ||
  isDirectScript(import.meta.url, 'gemini_cli_hook.js')
) {
  void runGeminiCliHook();
}
